<template>
  <div class="container"><TopBar /><h1>Buscar movimientos</h1><section class="card filters"><div class="quick"><button v-for="item in quickRanges" :key="item.label" @click="setRange(item.days)">{{ item.label }}</button><button class="clear" @click="clearFilters">Limpiar</button></div><div class="grid"><label>Desde<input v-model="filters.from" type="date" /></label><label>Hasta<input v-model="filters.to" type="date" /></label><label>Tipo<select v-model="filters.type"><option value="">Todos</option><option value="income">Ingresos</option><option value="expense">Gastos</option></select></label><label>Integrante<select v-model="filters.recordedById"><option value="">Todos</option><option v-for="user in members" :key="user.id" :value="user.id">{{ user.name || user.email }}</option></select></label><label>Categoría<input v-model="filters.category" placeholder="Ej: Comida" /></label><label>Descripción<input v-model="filters.search" placeholder="Buscar texto" /></label></div><button class="search" @click="load">Buscar</button></section><section class="summary"><div><small>Ingresos</small><strong class="income">{{ money(income()) }}</strong></div><div><small>Gastos</small><strong class="expense">{{ money(expense()) }}</strong></div><div><small>Balance</small><strong>{{ money(income() - expense()) }}</strong></div></section><section class="card"><p v-if="loading">Consultando...</p><p v-else-if="!items.length" class="empty">No hay movimientos para los filtros seleccionados.</p><div v-for="item in items" v-else :key="item.id" class="item"><div><strong>{{ item.category }}</strong><span>{{ item.description || 'Sin descripción' }} · {{ new Date(item.date).toLocaleDateString('es-CO') }}</span></div><strong :class="item.type">{{ item.type === 'income' ? '+' : '-' }} {{ money(item.amount) }}</strong></div></section></div>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import TopBar from '~/components/TopBar.vue'; import { useMvpUserId } from '~/composables/useMvpUserId'
const userId = useMvpUserId(); const items = ref<any[]>([]); const members = ref<any[]>([]); const loading = ref(false); const filters = reactive({ from: '', to: '', type: '', recordedById: '', category: '', search: '' })
const quickRanges = [{ label: 'Hoy', days: 0 }, { label: 'Ayer', days: 1 }, { label: 'Últimos 7 días', days: 7 }, { label: 'Este mes', days: 30 }]
const money = (n: number) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP' }).format(n || 0)
const iso = (date: Date) => { const y = date.getFullYear(); const m = String(date.getMonth() + 1).padStart(2, '0'); const d = String(date.getDate()).padStart(2, '0'); return `${y}-${m}-${d}` }
const setRange = (days: number) => { const now = new Date(); filters.to = iso(now); if (days === 30) filters.from = iso(new Date(now.getFullYear(), now.getMonth(), 1)); else { const from = new Date(now); from.setDate(now.getDate() - days); filters.from = iso(from) } load() }
const clearFilters = () => { Object.assign(filters, { from: '', to: '', type: '', recordedById: '', category: '', search: '' }); load() }
const load = async () => { if (!userId) return; loading.value = true; try { items.value = await $fetch('/api/transactions', { params: { userId, ...filters, pageSize: 100 } }) as any[] } finally { loading.value = false } }
const income = () => items.value.filter((item) => item.type === 'income').reduce((sum, item) => sum + item.amount, 0)
const expense = () => items.value.filter((item) => item.type === 'expense').reduce((sum, item) => sum + item.amount, 0)
onMounted(async () => { if (userId) members.value = await $fetch('/api/users', { params: { userId } }) as any[]; await load() })
</script>
<style scoped>.container{max-width:1000px;margin:auto;color:#fff}.card,.summary>div{background:rgba(20,30,58,.88);border:1px solid rgba(139,92,246,.22);border-radius:18px;padding:16px;margin:14px 0}.quick{display:flex;gap:8px;flex-wrap:wrap}.quick button,.search{border:0;border-radius:10px;padding:10px 12px;background:#24345c;color:#fff;font-weight:700}.quick .clear{background:#be185d}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:16px 0}.grid label{display:grid;gap:5px;font-size:13px;font-weight:700}.grid input,.grid select{padding:10px;border:1px solid rgba(139,92,246,.3);border-radius:10px;background:#101a33;color:#fff}.search{background:linear-gradient(135deg,#8b5cf6,#ec4899)}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.summary div{display:grid;gap:6px}.summary small{opacity:.7}.income{color:#4ade80}.expense{color:#fb7185}.item{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid #33436d}.item span{display:block;opacity:.7;font-size:13px;margin-top:4px}.income{color:#4ade80}.expense{color:#fb7185}.empty{opacity:.75}@media(max-width:700px){.grid,.summary{grid-template-columns:1fr}.item{align-items:flex-start;flex-direction:column}}
</style>
